from solution import is_simple_power
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


def _ref_positive(x, n):
    # obviously correct reference for n >= 2, x >= 1, k >= 0
    assert n >= 2 and x >= 1
    p = 1
    while p < x:
        p *= n
        if p > x:
            break
    return p == x


# ---- explicit spec examples ----
@pytest.mark.parametrize(
    "x,n,expected",
    [
        (1, 4, True),
        (2, 2, True),
        (8, 2, True),
        (3, 2, False),
        (3, 1, False),
        (5, 3, False),
    ],
)
def test_spec_examples(x, n, expected):
    assert is_simple_power(x, n) is expected or is_simple_power(x, n) == expected


def test_one_is_power_of_any_nonzero_base():
    for n in [2, 3, 4, 5, 10, -2, -3, 2**10]:
        assert is_simple_power(1, n) is True or is_simple_power(1, n) == True


def test_n_equals_one_only_one_is_power():
    # 1**k == 1 for all k, so x != 1 can never be a power of 1
    for x in [2, 3, 5, 8, 9, 16, 100]:
        assert is_simple_power(x, 1) == False


def test_zero_base_with_nonzero_n_is_false():
    # n**k != 0 for n != 0, k >= 0
    for n in [2, 3, 4, 10, -2]:
        assert is_simple_power(0, n) == False


def test_nonzero_x_is_not_power_of_zero():
    # 0**k is 0 (k>0) or 1 (k==0); never 2,3,5,...
    for x in [2, 3, 5, 8, 9, 100]:
        assert is_simple_power(x, 0) == False


def test_returns_bool_for_valid_inputs():
    assert is_simple_power(8, 2) in (True, False)
    assert type(is_simple_power(8, 2)) is bool
    assert type(is_simple_power(3, 2)) is bool


@given(n=st.integers(min_value=2, max_value=10), k=st.integers(min_value=0, max_value=12))
def test_constructed_powers_are_true(n, k):
    x = n ** k
    assert is_simple_power(x, n) == True


@given(n=st.integers(min_value=2, max_value=10), k=st.integers(min_value=0, max_value=12))
def test_off_by_one_is_false(n, k):
    x = n ** k
    # x+1 is never a power of n for n>=2 except tiny corner; verify with reference
    if not _ref_positive(x + 1, n):
        assert is_simple_power(x + 1, n) == False
    if x > 1 and not _ref_positive(x - 1, n):
        assert is_simple_power(x - 1, n) == False


@given(
    x=st.integers(min_value=1, max_value=2000),
    n=st.integers(min_value=2, max_value=20),
)
def test_matches_reference_model(x, n):
    assert is_simple_power(x, n) == _ref_positive(x, n)


def test_large_powers_exact():
    # float-division implementation loses precision for large values
    assert is_simple_power(3 ** 35, 3) == True
    assert is_simple_power(5 ** 20, 5) == True
    assert is_simple_power(7 ** 18, 7) == True
    assert is_simple_power(2 ** 80, 2) == True
    assert is_simple_power(10 ** 18, 10) == True


def test_large_non_powers_are_false():
    assert is_simple_power(3 ** 35 + 1, 3) == False
    assert is_simple_power(3 ** 35 - 1, 3) == False
    assert is_simple_power(5 ** 20 + 1, 5) == False
    assert is_simple_power(2 ** 80 + 1, 2) == False


@given(
    x=st.integers(min_value=2, max_value=500),
    n=st.integers(min_value=2, max_value=20),
)
def test_multiplying_non_power_stays_false_or_true_consistent(x, n):
    # metamorphic: if x is not a power, x*n may or may not be; but reference decides
    expected = _ref_positive(x, n)
    assert is_simple_power(x, n) == expected
    expected2 = _ref_positive(x * n, n)
    # x*n is a power iff x is a power (for x>=1, n>=2): since x*n = n**(k+1) iff x=n**k
    assert expected2 == expected or (x == 1)
    assert is_simple_power(x * n, n) == expected2
